package dev.youth;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class ScheduleToolsTest{Instant n=Instant.parse("2030-01-01T09:00:00Z");@Test void adjacentSlotsMerge(){var x=new Scheduler.Slot("v",n,n.plusSeconds(1800),Set.of("a"));var y=new Scheduler.Slot("v",n.plusSeconds(1800),n.plusSeconds(3600),Set.of("a"));assertEquals(1,new AvailabilityNormalizer().merge(List.of(y,x)).size());}@Test void metricsSummarizePlan(){var p=new Scheduler.Plan(List.of(new Scheduler.Assignment("r","v",n,n.plusSeconds(1800))),Map.of());var m=PlanMetrics.from(p);assertEquals(30,m.scheduledMinutes());assertEquals(30,m.minutesByVolunteer().get("v"));}@Test void validationFindsOverlap(){var a=new Scheduler.Assignment("a","v",n,n.plusSeconds(1800));var b=new Scheduler.Assignment("b","v",n.plusSeconds(900),n.plusSeconds(2700));assertEquals(1,new ScheduleValidator().conflicts(new Scheduler.Plan(List.of(a,b),Map.of())).size());}}
